const all=window.MethodCards,by=Object.fromEntries(all.map(c=>[c.id,c])),data={};
const css=`@page{size:A4 landscape;margin:10mm}*{box-sizing:border-box}.mm-page{font-family:Arial,sans-serif;color:#183f48;background:#fff;width:277mm;height:188mm;padding:7mm 9mm;position:relative;break-after:page;overflow:hidden;border:1px solid #d4e1e1;margin:0 auto 8mm}.mm-page:last-child{break-after:auto}.mm-head{border-bottom:2px solid #176b77;display:flex;align-items:center;justify-content:space-between;padding-bottom:3mm;margin-bottom:4mm}.mm-head h1{font-size:21pt;line-height:1.1;margin:0}.mm-head small{font-size:9pt;letter-spacing:1px}.mm-brand{font-size:10pt;font-weight:bold}.mm-intro{font-size:11pt;margin:0 0 4mm;line-height:1.35}.mm-content{height:143mm}.mm-footer{position:absolute;bottom:4mm;left:9mm;right:9mm;font-size:8pt;color:#52696e;display:flex;justify-content:space-between;border-top:1px solid #d4e1e1;padding-top:2mm}.mm-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:4mm}.mm-grid.three{grid-template-columns:repeat(3,minmax(0,1fr))}.mm-grid.four{grid-template-columns:repeat(4,minmax(0,1fr))}.mm-box{border:1px solid #90aeb1;border-radius:3mm;padding:4mm;min-height:30mm;position:relative}.mm-box h2{font-size:13pt;margin:0 0 3mm}.mm-box p{font-size:11pt;line-height:1.35;margin:1mm 0}.mm-lines{background:repeating-linear-gradient(to bottom,transparent 0,transparent 8mm,#b6c8ca 8mm,#b6c8ca 8.2mm);height:32mm}.mm-board{display:block;width:100%;max-height:110mm;margin:auto}.mm-board text{font-family:Arial,sans-serif}.mm-cut{border:1px dashed #78979d;min-height:34mm}.mm-table{border-collapse:collapse;width:100%;font-size:11pt}.mm-table th,.mm-table td{border:1px solid #90aeb1;padding:3mm;text-align:left;height:10mm}.mm-table th{background:#edf4f3}.mm-hint{background:#fff6d9;padding:3mm;font-size:11pt;border-left:3px solid #cf9b32}.mm-large{font-size:18pt!important;line-height:1.3!important}.mm-placemat{height:139mm;position:relative;display:grid;grid-template-columns:1fr 1fr;grid-template-rows:1fr 1fr;border:2px solid #176b77}.mm-outer{padding:5mm;border:1px solid #93aeb0;font-size:12pt}.mm-outer:nth-child(n+3){display:flex;flex-direction:column;justify-content:flex-end}.mm-outer p{margin:0}.mm-outer .mm-lines{width:80%;height:30mm}.mm-middle{position:absolute;left:31%;top:33%;width:38%;height:28%;border:2px solid #176b77;border-radius:3mm;background:white;padding:3mm;text-align:center;font-size:12pt;box-shadow:0 0 0 3mm white}.mm-middle .mm-lines{height:24mm}.mm-check{display:inline-block;width:4mm;height:4mm;border:1px solid #42646b;margin-right:2mm}.mm-domino{display:grid;grid-template-columns:1fr 1fr;min-height:27mm;border:1px dashed #698e96;font-size:12pt}.mm-domino span{padding:4mm;display:flex;align-items:center;justify-content:center;text-align:center}.mm-domino span+span{border-left:2px solid #176b77}.mm-bingo{border-collapse:collapse;width:100%;font-size:16pt}.mm-bingo td{border:1.5px solid #176b77;text-align:center;height:31mm;width:33.3%}.mm-sign{height:57mm;display:flex;align-items:center;justify-content:center;text-align:center;font-size:26pt;font-weight:bold}.mm-map{width:100%;height:133mm}.mm-mini-board{max-height:62mm}.mm-mini-board .mm-board{height:46mm;max-height:46mm}.mm-speech{border:2px solid #176b77;border-radius:8mm;padding:5mm;font-size:14pt;min-height:30mm}.mm-score{font-size:13pt}.mm-cross{border-collapse:collapse}.mm-cross td{height:9mm;width:9mm;min-width:9mm;position:relative;border:1px solid white;background:#e7eeee}.mm-cross td.open{background:white;border:2px solid #567980}.mm-cross td b{position:absolute;top:.4mm;left:.6mm;font-size:7pt}.mm-illustration{width:100%;height:auto;display:block}.mm-figuretoken{height:19mm;width:19mm}.mm-no-print{font-family:Arial;padding:15px;text-align:center;background:#edf4f3}@media print{body{margin:0!important;background:white!important}.mm-page{margin:0;border:0}.mm-no-print{display:none!important}a{color:inherit;text-decoration:none}}@media print{.inspirationcard,.mm-page{color:#222!important}.mm-lines{background:repeating-linear-gradient(to bottom,transparent 0,transparent 8mm,#bbb 8mm,#bbb 8.2mm)!important}#methodcards .methodtile{background:white!important;border-color:#777!important;box-shadow:none!important}.methodvisual{background:white!important;border:1px solid #555!important}.methodvisual svg,.mm-page svg{filter:grayscale(1)}.methodvisual svg rect:not(.mm-board *),.mm-illustration rect:not(.mm-board *),.mm-map rect{fill:white!important;stroke:#666!important}.methodvisual svg circle,.mm-illustration circle{fill:white!important;stroke:#555!important}.methodvisual figcaption{color:#222!important;background:white!important}.mm-page *{border-color:#777!important}.mm-table th,.mm-hint{background:white!important}.mm-middle{border-radius:0!important;background:white!important}.mm-page svg [fill="#c3d2d1"]{fill:#dedede!important}.mm-page svg [fill="#faf7ee"]{fill:white!important}.mm-page svg [fill="#edf4f3"],.mm-page svg [fill="#e7eeee"]{fill:white!important}.mm-head,.mm-footer{color:#333!important}.mm-page svg text{fill:#222!important}}`;
const lines=(h=32)=>`<div class="mm-lines" style="height:${h}mm"></div>`;
const box=(t,b='',cl='')=>`<section class="mm-box ${cl}"><h2>${esc(t)}</h2>${b}</section>`;
const para=t=>`<p>${esc(t)}</p>`;
const fields=names=>names.map(n=>box(n,lines(25))).join('');
const grid=(s,c='')=>`<div class="mm-grid ${c}">${s}</div>`;
const table=(heads,rows)=>`<table class="mm-table"><thead><tr>${heads.map(x=>'<th>'+esc(x)+'</th>').join('')}</tr></thead><tbody>${rows.map(r=>'<tr>'+r.map(x=>'<td>'+esc(x)+'</td>').join('')+'</tr>').join('')}</tbody></table>`;
const cut=items=>grid(items.map(x=>box(x[0],para(x[1]),'mm-cut')).join(''));
const checks=items=>items.map(x=>`<p><span class="mm-check"></span>${esc(x)}</p>`).join('');
function pieces(fen){if(typeof fen==='object')return fen;let o={};(fen||'8/8/8/8/8/8/8/8').split(' ')[0].split('/').forEach((r,y)=>{let x=0;for(const c of r){if(/\d/.test(c))x+=+c;else{o['abcdefgh'[x]+(8-y)]=c;x++}}});return o}
function token(p,x,y,size){const name='Chess_'+(p===p.toUpperCase()?p.toLowerCase()+'lt':p+'dt')+'45.svg';return `<image href="${window.FIGURE_DATA?.[name]||'assets/'+name}" x="${x}" y="${y}" width="${size}" height="${size}"/>`}
function board(setup={},marks=[],arrows=[]){let s='';const ps=pieces(setup);for(let y=0;y<8;y++)for(let x=0;x<8;x++){const sq='abcdefgh'[x]+(8-y),xx=28+x*40,yy=28+y*40;s+=`<rect x="${xx}" y="${yy}" width="40" height="40" fill="${(x+y)%2?'#c3d2d1':'#faf7ee'}"/>`;if(marks.includes(sq))s+=`<rect x="${xx+2}" y="${yy+2}" width="36" height="36" fill="none" stroke="#bc7b15" stroke-width="3"/>`;if(ps[sq])s+=token(ps[sq],xx+2,yy+2,36)}for(let n=0;n<8;n++)s+=`<text x="${48+n*40}" y="369" text-anchor="middle" font-size="14">${'abcdefgh'[n]}</text><text x="15" y="${53+n*40}" text-anchor="middle" font-size="14">${8-n}</text>`;for(const [a,b]of arrows){const xy=q=>[48+'abcdefgh'.indexOf(q[0])*40,48+(8-Number(q[1]))*40];const [x,y]=xy(a),[xx,yy]=xy(b);s+=`<path d="M${x} ${y} L${xx} ${yy}" stroke="#b86d13" stroke-width="5" marker-end="url(#mma)"/>`}const partial=!Object.values(ps).includes('K')||!Object.values(ps).includes('k');if(partial)s+='<text x="190" y="397" text-anchor="middle" font-size="12" fill="#333">Übungsbrett zur Zugweise</text>';return `<svg class="mm-board" viewBox="0 0 380 ${partial?410:380}" role="img" aria-label="Schachbrett mit Koordinaten"><defs><marker id="mma" markerWidth="6" markerHeight="6" refX="5" refY="3" orient="auto"><path d="M0 0 L6 3 L0 6" fill="#b86d13"/></marker></defs>${s}</svg>`}
const start='rnbqkbnr/pppppppp/8/8/8/8/PPPPPPPP/RNBQKBNR';
const knight={b1:'N'},rook={d4:'R'},block={a1:'R',a3:'P'},three={a1:'K',d2:'R',h8:'k'};
const mates=[['6k1/5ppp/8/8/8/8/8/R5K1','Ta8#','a1','a8'],['7k/8/5KQ1/8/8/8/8/8','Dg7#','g6','g7'],['6k1/5ppp/8/8/8/8/8/1R4K1','Tb8#','b1','b8']];
function page(title,intro,html,teacher=false){return {title,intro,html,teacher}}
function reg(id,pages,scene='sheet',labels=[],supply='Stifte; bei Bedarf Schachbrett und Figuren.'){data[id]={pages,scene,labels,supply};}
function sheet(id,title,prompt,setup,responses,answer,scene='board'){reg(id,[page(title,prompt,grid(box('Brettbild · Weiß unten',board(setup))+box('Meine Gedanken · zeigen, sagen oder notieren',fields(responses))),false),...(answer?[page('Hinweise für die Lehrkraft','Nur zur Kontrolle. Separat ausgeben.',box('Zum Schachbeispiel',para(answer)),true)]:[])],scene,[title,...responses]);}
