const base=[
['discussion','Was kann der Turm?','Markiere Felder, die der Turm von d4 in einem Zug erreichen kann.',rook,['Meine Beobachtung','Meine Begründung'],'Der Turm erreicht 14 andere Felder: sieben auf der d-Linie und sieben auf Reihe 4.'],
['demo','So springt der Springer','Zeige b1 und c3. Erkläre den Sprung in eigenen Worten.',knight,['So zeige ich den Zug','So erkläre ich die L-Form'],'b1–c3 ist ein Springerzug: eine Linie und zwei Reihen.'],
['errors','Stimmt diese Behauptung?','„Ein Springer darf auf ein Feld mit einer eigenen Figur ziehen.“ Prüfe b1–d2.',{b1:'N',d2:'R'},['Mein Urteil','Die richtige Regel'],'Nein. Auf d2 steht der eigene Turm. Eigene Figuren werden weder geschlagen noch auf demselben Feld abgestellt.'],
['partner','Einer erklärt, einer prüft','Person A erklärt b1–c3. Person B prüft. Anschließend wechseln.',knight,['A: So geht der Zug','B: Das habe ich geprüft'],'b1–c3 ist auf diesem Übungsbrett möglich. Auf vollständigen Stellungen zusätzlich die Königssicherheit prüfen.'],
['puzzle','Finde die Springerziele','Welche Felder erreicht der Springer b1 auf diesem leeren Übungsbrett?',knight,['Meine Zielfelder','So habe ich geprüft'],'a3, c3 und d2.'],
['mini','Turm auf Besuch','Der Turm startet auf a1. Besuche zuerst a4 und danach d4.',{a1:'R'},['Mein erster Zug','Mein zweiter Zug'],'a1–a4, anschließend a4–d4. Eigenes Wegspiel ohne Könige.'],
['predict','Erst vorstellen, dann ziehen','Stelle dir b1–c3 vor, ohne zu ziehen. Welche Felder greift der Springer danach an? Sage voraus, ziehe und prüfe.',knight,['Diese Felder vermute ich nach b1–c3','Diese Felder habe ich geprüft'],'Von c3 greift der Springer a2, a4, b1, b5, d1, d5, e2 und e4 an. Das Startfeld c3 zählt nicht mit.'],
['reciprocal','Erklären und nachfragen','Erkläre die Wege des Läufers von c1. Dein Partner stellt eine Warum-Frage.',{c1:'B'},['Meine Erklärung','Die Frage meines Partners'],'Der Läufer zieht diagonal und bleibt auf dunklen Feldern.'],
['silent','Meine stillen Turmwege','Arbeite zunächst ohne Zuruf. Zeichne die Turmwege von d4 ein.',rook,['Das habe ich entdeckt','Dazu habe ich eine Frage'],'Vier Richtungen, 14 erreichbare Felder auf leerem Übungsbrett.'],
['visual','Was fällt dir auf?','Schau das Bild genau an. Stelle selbst eine Frage zum Läufer.',{c1:'B'},['Das sehe ich','Das möchte ich wissen'],null],
['coach','Fragen helfen beim Denken','Überlege, wohin der Turm ziehen kann. Der Coach stellt Fragen und verrät keinen Zug.',block,['Meine Zugidee','Diese Frage hat mir geholfen'],'Nach oben stoppt der eigene Bauer a3 den Turm: a2 ist frei, a3 und Felder dahinter sind nicht erreichbar.'],
['question','Meine Frage an das Brett','Formuliere eine Frage zum Läufer. Ein anderes Kind beantwortet sie.',{c1:'B'},['Meine Frage','Antwort mit Begründung'],'Beispielfrage: Kann der Läufer weiße Felder erreichen? Nein, dieser Läufer bleibt auf dunklen Feldern.'],
['teachback','Ohne Vorlage erklären','Erkläre deinem Partner die Wege des Turms. Lass ihn einen Zug zeigen.',rook,['Mein Merksatz','So hat mein Partner ihn verstanden'],'Der Turm zieht waagerecht oder senkrecht; er springt nicht über Figuren.'],
['worked','Ergänze den fehlenden Gedanken','„Der Turm darf von a1 nach a5, weil …“ Ergänze und zeichne den Weg.',{a1:'R'},['Weil …','Diese Felder habe ich geprüft'],'a2, a3 und a4 sind frei, a5 ist frei. Der Turm zieht senkrecht.'],
['reverse','Baue das Hindernis','Der Turm a1 soll a5 nicht erreichen können. Zeichne einen eigenen Bauern passend ein.',{a1:'R'},['Mein Bauernfeld','Warum es den Weg versperrt'],'Zum Beispiel a2, a3 oder a4. Auch ein eigener Bauer auf a5 verhindert die Landung.'],
['secure','Regel und Beispiel','Zeige einen Läuferweg und halte die passende Regel fest.',{c1:'B'},['Mein Regelsatz','Mein Beispielzug'],'Zum Beispiel c1–h6. Der Läufer zieht diagonal und bleibt auf seiner Feldfarbe.'],
['repair','Meine Idee verbessern','Jemand möchte den Turm von a1 nach c3 ziehen. Erkläre den Fehler und zeige einen erlaubten Zug.',{a1:'R'},['Das war der Irrtum','So geht es richtig'],'a1–c3 ist diagonal und damit kein Turmzug. Möglich wäre a1–a3 oder a1–c1.'],
['transfercard','Gleiche Regel, anderes Feld','Vorher stand der Turm auf a1. Welche Wege hat er nun von d4?',rook,['Das bleibt gleich','Das ist anders'],'Gleiche Zugweise. Von d4 kann er in vier Richtungen ziehen; von a1 nur in zwei. Auf leerem Brett jeweils 14 Ziele.'],
['mental','Ein Zug im Kopf','Sage b1–c3 an, ohne zu ziehen. Zeige danach aus dem Gedächtnis das Zielfeld.',knight,['Mein vorgestelltes Zielfeld','Kontrolle am Brett'],'c3.'],
['inspiration-21','Ich denke laut','Sprich deine Gedanken beim Prüfen eines Turmzugs aus. Die anderen hören erst zu.',block,['Meine Gedankenschritte','Eine hilfreiche Rückfrage'],'Bei a1–a5 blockiert a3 den Weg. a1–a2 oder waagerechte Züge sind auf diesem Übungsbrett möglich.'],
['inspiration-44','Erst schätzen, dann zählen','Wie viele andere Felder erreicht der Turm d4 auf leerem Brett?',rook,['Meine Schätzung','Gezählt und markiert'],'14 andere Felder. Das Startfeld d4 wird nicht mitgezählt.']
];base.forEach(x=>sheet(...x));
