reg('placemat',[page('Placemat · Fair spielen','1. Jede Person schreibt im eigenen Feld. 2. Vergleicht eure Ideen. 3. Einigt euch in der Mitte auf drei Regeln.',`<div class="mm-placemat">${[1,2,3,4].map(n=>`<div class="mm-outer"><b>Person ${n} · Meine Fairplay-Ideen</b><p>Was hilft uns beim gemeinsamen Schachspielen?</p>${lines(31)}</div>`).join('')}<div class="mm-middle"><b>Unsere drei Fairplay-Regeln</b>${lines(24)}</div></div>`),page('Placemat · Unser Schachthema','Thema / Frage: ______________________________________________________',`<div class="mm-placemat">${[1,2,3,4].map(n=>`<div class="mm-outer"><b>Person ${n} · Erst selbst nachdenken</b>${lines(35)}</div>`).join('')}<div class="mm-middle"><b>Unsere gemeinsame Schachidee</b>${lines(24)}</div></div>`)],'placemat',['Eigene Ideen','Vier Perspektiven','Gemeinsame Regeln'],'Stifte; für vier Kinder möglichst auf A3 vergrößern.');
