function mapSvg(center,labels,cluster=false){return `<svg class="mm-map" viewBox="0 0 1000 460" role="img" aria-label="Gedankenkarte zum Schach"><g fill="none" stroke="#708e94" stroke-width="2">${labels.map((t,i)=>{const x=i%2?760:240,y=70+Math.floor(i/2)*155;return `<path d="M500 230 L${x} ${y}"/>`}).join('')}</g><rect x="380" y="192" width="240" height="76" rx="20" fill="#edf4f3" stroke="#176b77" stroke-width="3"/><text x="500" y="238" text-anchor="middle" font-size="24" fill="#183f48">${esc(center)}</text>${labels.map((t,i)=>{const x=i%2?760:240,y=70+Math.floor(i/2)*155;return `<rect x="${x-150}" y="${y-45}" width="300" height="100" rx="${cluster?45:10}" fill="white" stroke="#90aeb1"/><text x="${x}" y="${y-15}" text-anchor="middle" font-size="19">${esc(t)}</text><path d="M${x-130} ${y+15} H${x+130} M${x-130} ${y+40} H${x+130}" stroke="#b6c8ca"/>`}).join('')}</svg>`}
